"""
Template filters for responsive images: WebP URL and srcset.
Used with the image pipeline (WebP + responsive sizes in same directory).
No backend or API changes.
"""
import re
from django import template

register = template.Library()

# Widths generated by core/image_pipeline (same order for srcset)
RESPONSIVE_WIDTHS = (300, 600, 1200, 2000)


@register.filter
def webp_url(url):
    """
    Return the WebP version of an image URL for <source type="image/webp">.
    Example: /media/profiles/xyz.jpg -> /media/profiles/xyz.webp
    If url is empty or not a supported extension, returns original.
    """
    if not url or not isinstance(url, str):
        return url or ""
    # Replace last extension with .webp (handles .jpg, .jpeg, .png)
    return re.sub(r"\.(jpe?g|png)(\?.*)?$", r".webp\2", url, flags=re.IGNORECASE)


@register.filter
def responsive_srcset(url):
    """
    Return srcset value for responsive image (pipeline generates _300, _600, _1200, _2000).
    Example: /media/profiles/xyz.jpg -> "url_300 300w, url_600 600w, url_1200 1200w, url_2000 2000w"
    """
    if not url or not isinstance(url, str):
        return ""
    # Insert _WIDTH before extension
    parts = re.sub(r"\.(jpe?g|png)(\?.*)?$", lambda m: " placeholder " + m.group(0), url, flags=re.IGNORECASE).split(" placeholder ", 1)
    if len(parts) != 2:
        return ""
    base, ext_part = parts[0], parts[1]
    return ", ".join(f"{base}_{w}{ext_part} {w}w" for w in RESPONSIVE_WIDTHS)


@register.filter
def thumb_url(url):
    """
    Return the 300px thumbnail URL (pipeline generates base_thumb.jpg/png).
    """
    if not url or not isinstance(url, str):
        return url or ""
    return re.sub(r"\.(jpe?g|png)(\?.*)?$", r"_thumb.\1\2", url, flags=re.IGNORECASE)
